import {createProxyErrorHelper} from '../../apps/api/src/ops/proxy-errors.ts';
import {fixture} from './b033-runtime.mjs';
import {createApp} from '../../apps/api/src/app.ts';
import {createServer} from 'node:net';
import {spawn,spawnSync} from 'node:child_process';
import {mkdir,writeFile,readFile} from 'node:fs/promises';
import path from 'node:path';
import {assertSchema} from '../../packages/contracts/src/index.mjs';
const check=(v,m)=>{if(!v)throw Error(m);};
async function port(){const s=createServer();await new Promise(r=>s.listen(0,'127.0.0.1',r));const p=s.address().port;await new Promise(r=>s.close(r));return p;}
export async function runChecks(client,runtime,test){
 const f=await fixture(client,runtime,1),app=await createApp(f.auth,{localOps:{auth:f.auth,privateRoot:f.byteRoot}});await app.listen({host:'127.0.0.1',port:0});
 const binary=path.resolve('experiments/g01/.runtime/x07-tools/nginx-1.31.8/nginx.exe'),prefix=path.join(runtime,'nginx'),listen=await port(),dead=await port();await mkdir(prefix+'/logs',{recursive:true});await mkdir(prefix+'/conf',{recursive:true});await mkdir(prefix+'/temp',{recursive:true});
 const helper=await createProxyErrorHelper();const sockets=new Set();const hanging=createServer(socket=>{sockets.add(socket);socket.on('close',()=>sockets.delete(socket));});await new Promise(r=>hanging.listen(0,'127.0.0.1',r));const hangingPort=hanging.address().port;
 const errors=[413,502,503,504].map(status=>`location @e${status} { proxy_method GET; proxy_pass_request_body off; proxy_set_header Content-Length ""; proxy_set_header X-Local-Proxy-Key ${helper.key}; proxy_set_header X-Local-Proxy-Status ${status}; proxy_set_header X-Local-Proxy-Request-Id $request_id; proxy_hide_header X-Request-Id; proxy_hide_header Cache-Control; proxy_hide_header X-Content-Type-Options; proxy_pass ${helper.origin}; }`).join('\n');
 const config=`worker_processes 1; daemon off; error_log logs/error.log; pid logs/nginx.pid; events { worker_connections 64; } http { access_log logs/access.log; map $time_iso8601 $utc { ~^(?<utcbase>.+)[+]00:00$ \${utcbase}Z; default ""; } server { listen 127.0.0.1:${listen}; client_max_body_size 1m; add_header Cache-Control no-store always; add_header X-Content-Type-Options nosniff always; add_header X-Request-Id $request_id always; error_page 413 = @e413; error_page 502 = @e502; error_page 503 = @e503; error_page 504 = @e504; location /api/v1/ { proxy_pass ${app.listeningOrigin}; proxy_hide_header X-Request-Id; } location = /api/v1/proxy-dead { proxy_pass http://127.0.0.1:${dead}; } location = /api/v1/proxy-maintenance { return 503; } location = /api/v1/proxy-timeout { proxy_read_timeout 200ms; proxy_pass http://127.0.0.1:${hangingPort}; } location = /healthz { default_type application/json; return 200 '{"proxyLive":true}'; } location / { return 404; } ${errors} } }`;
 await writeFile(prefix+'/conf/nginx.conf',config,{flag:'wx'});const args=['-p',prefix.replaceAll('\\','/')+'/', '-c','conf/nginx.conf'],env={...process.env,TZ:'UTC'};const syntax=spawnSync(binary,[...args,'-t'],{encoding:'utf8',env,windowsHide:true});await writeFile(prefix+'/syntax.txt',syntax.stdout+syntax.stderr,{flag:'wx'});if(syntax.status!==0){await app.close();await helper.close();throw Error('nginx syntax');}let stderr='',child=spawn(binary,args,{env,windowsHide:true,stdio:['ignore','pipe','pipe']});child.stderr.on('data',b=>stderr+=b);const origin='http://127.0.0.1:'+listen;
 try{let up=false;for(let i=0;i<30;i++){try{if((await fetch(origin+'/healthz')).ok){up=true;break;}}catch{}await new Promise(r=>setTimeout(r,100));}check(up,'owned Nginx ready');
 await test('B035-nginx-real-app-no-fallback',async()=>{for(const[p,status]of [['/api/v1/health/live',200],['/api/v1/unknown-private',404]]){const r=await fetch(origin+p),b=await r.json();check(r.status===status&&r.headers.get('cache-control').includes('no-store'),'JSON status/cache');assertSchema(status===200?'success-envelope.json':'error-envelope.json',b);}check((await fetch(origin+'/private-fixture-file')).status===404,'no private alias/SPA');return {realNginx:true,realApp:true,noPrivateAlias:true};});
 await test('B035-nginx-proxy-errors',async()=>{check((await fetch(helper.origin)).status===404,'helper private credential');check((await fetch(helper.origin,{headers:{'x-local-proxy-key':'g'.repeat(64)}})).status===404,'invalid credential shape');const invalid=await fetch(helper.origin,{headers:{'x-local-proxy-key':helper.key,'x-local-proxy-status':'200','x-local-proxy-request-id':'test'}});check(invalid.status===400,'helper status allowlist');const observed=[];for(const[p,status,options]of [['proxy-dead',502,{}],['proxy-maintenance',503,{}],['proxy-timeout',504,{}],['health/live',413,{method:'POST',headers:{'content-type':'application/json'},body:'x'.repeat(1048577)}]]){const r=await fetch(origin+'/api/v1/'+p,options),body=await r.text();observed.push({status:r.status,body,contentType:r.headers.get('content-type')});await writeFile(prefix+'/response-'+status+'.json',JSON.stringify(observed.at(-1),null,2),{flag:'wx'});check(r.status===status,'proxy status');const envelope=JSON.parse(body);assertSchema('error-envelope.json',envelope);check(Math.abs(Date.now()-Date.parse(envelope.serverNow))<10000,'actual fresh UTC');check(envelope.requestId===r.headers.get('x-request-id'),'proxy requestId bound');check(r.headers.get('cache-control').includes('no-store')&&r.headers.get('x-content-type-options')==='nosniff','proxy headers');}return {observed,actualUpstreamTimeout504:true};});
 }finally{const quit=spawnSync(binary,[...args,'-s','quit'],{encoding:'utf8',env,windowsHide:true});await writeFile(prefix+'/quit.txt',quit.stdout+quit.stderr,{flag:'wx'});await new Promise(r=>child.exitCode!==null?r():child.once('exit',r));await writeFile(prefix+'/stderr.txt',stderr,{flag:'wx'});await app.close();await helper.close();for(const socket of sockets)socket.destroy();await new Promise(r=>hanging.close(r));}
}





